+  }).join('');
+
+  document.querySelectorAll('tr.run').forEach((tr) => tr.addEventListener('click', (e) => {
+    if (e.target.closest('a')) return;
+    toggleDetail(tr);
+  }));
+}
+
+async function toggleDetail(tr) {
+  const next = tr.nextElementSibling;
+  if (next?.classList.contains('detail')) { next.remove(); return; }
+  document.querySelectorAll('tr.detail').forEach((d) => d.remove());
+  const id = tr.dataset.id;
+  const row = document.createElement('tr');
+  row.className = 'detail';
+  row.innerHTML = `<td colspan="10">Loading granular results…</td>`;
+  tr.after(row);
+
+  const get = (f) => fetch(`${DATA}runs/${id}/${f}`).then((r) => (r.ok ? r.json() : null)).catch(() => null);
+  const [vt, pw] = await Promise.all([get('vitest.json'), get('playwright.json')]);
+
+  const vitestList = (filter, title) => {
+    if (!vt) return `<div><h3>${title}</h3><div class="tlist">no data</div></div>`;
+    const rows = [];
+    for (const f of vt.testResults ?? []) {
+      if (!filter(f.name)) continue;
+      const short = f.name.split('/src/')[1] ?? f.name;
+      for (const t of f.assertionResults ?? []) {
+        const ok = t.status === 'passed';
+        rows.push(`<div><span class="${ok ? 'ok' : 'bad'}">${ok ? '✓' : '✗'}</span> <span title="${short}">${t.fullName}</span><span class="dur">${Math.round(t.duration ?? 0)}ms</span></div>`);
+        if (!ok && t.failureMessages?.length) rows.push(`<div class="err">${String(t.failureMessages[0]).slice(0, 400).replace(/</g, '&lt;')}</div>`);
+      }
+    }
+    return `<div><h3>${title} (${rows.length})</h3><div class="tlist">${rows.join('') || 'none'}</div></div>`;
+  };
+
+  const pwRows = [];
+  const walk = (suite, path) => {
+    for (const s of suite.suites ?? []) walk(s, path);
+    for (const spec of suite.specs ?? []) {
+      for (const t of spec.tests ?? []) {
+        const res = t.results?.[t.results.length - 1];
+        const ok = spec.ok;
+        pwRows.push(`<div><span class="${ok ? 'ok' : 'bad'}">${ok ? '✓' : '✗'}</span> ${spec.title}<span class="dur">${Math.round(res?.duration ?? 0)}ms${t.status === 'flaky' ? ' · flaky' : ''}</span></div>`);
+        if (!ok && res?.error?.message) pwRows.push(`<div class="err">${String(res.error.message).slice(0, 400).replace(/</g, '&lt;')}</div>`);
+      }
+    }
+  };
+  if (pw) for (const s of pw.suites ?? []) walk(s, '');
+  const isIntegration = (n) => /(integrity|missionDb)\.test\.ts$/.test(n);
+
+  row.innerHTML = `<td colspan="10"><div class="detail-grid">
+    ${vitestList((n) => !isIntegration(n), 'Unit tests')}
+    ${vitestList(isIntegration, 'Integration tests')}
+    <div><h3>E2E tests (${pwRows.length})</h3><div class="tlist">${pwRows.join('') || 'no data'}</div></div>
+  </div></td>`;
+}
+
+['f-context', 'f-range', 'f-suite'].forEach((id) => $(id).addEventListener('change', render));
+$('refresh').addEventListener('click', load);
+setInterval(load, 60000);
+load();
+</script>
+</body>
+</html>
